CREATE TRIGGER service_attribution_maintenance_insert AFTER INSERT ON maintenance WHEN NEW.people_metadata IS NOT NULL AND json_valid(NEW.people_metadata) AND json_extract(NEW.people_metadata,'$.executor.name')=NEW.responsible BEGIN
